'use strict';

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var tryRequire = require( '@stdlib/utils/try-require' );
var Float64Array = require( '@stdlib/array/float64' );
var register = require( './common.js' );
var factory = require( './../lib/factory.js' );
var canUseNative = require( './../lib/can_use_native.js' );
var base = require( './../lib/base.js' );
var publicFn = require( './../lib' );
var jsFn = require( './../lib/main.js' );
var native = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var addon = tryRequire( resolve( __dirname, './../src/addon.node' ) );

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof publicFn, 'function', 'main export is a function' );
	t.end();
});

if ( !(native instanceof Error) ) {
	register( tape, native, 'native' );
}
tape( 'public index selects available backend', function test( t ) {
	var expected = ( native instanceof Error ) ? jsFn : native;
	t.strictEqual( publicFn, expected, 'public backend identity' );
	t.end();
});
tape( 'compiled addon and conservative metadata dispatch actually execute', {
	'skip': addon instanceof Error
}, function test( t ) {
	var offset;
	var calls;
	var work;
	var fn;
	var AF;
	var A;
	var i;

	calls = 0;

	fn = factory( function dispatch() {
		if ( canUseNative( arguments ) ) {
			calls += 1;
			return addon.apply( null, arguments );
		}
		return base.apply( null, arguments );
	});
	A = new Float64Array( [0.25] );
	AF = new Float64Array( [0.5] );
	work = new Float64Array( 2 );
	t.strictEqual( fn( 'row-major', 'upper', 1, A, 1, AF, 1, work ), 0.5, 'compiled typed call' );
	t.strictEqual( calls, 1, 'actual addon called' );
	t.strictEqual( fn.ndarray( 'upper', 1, A, 2147483648, 1, 0, AF, 1, -2147483648, 0, work, 1, 0 ), 0.5, 'wider unused metadata remains valid JS' );
	t.strictEqual( calls, 1, 'wider metadata falls back across integer ABIs' );
	for ( i = -3; i <= 3; i += 2 ) {
		offset = ( i < 0 ) ? 6 : 3;
		work = new Float64Array( 10 );
		t.strictEqual( fn.ndarray( 'upper', 1, A, 0, 0, 0, AF, 0, 0, 0, work, i, offset ), 0.5, 'actual strided scratch call' );
	}
	t.strictEqual( calls, 5, 'five instrumented actual native calls' );
	t.end();
});
